    private function getStokChace()
    {
        $tbl_1 = "_rek_pembantu_produk_cache";
        $wheres = array(// "sisa>" => 0,
            "periode" => "forever",
            "cabang_id" => my_cabang_id(),
            "gudang_id" => my_gudang_id(),
        );
        $this->db->where($wheres);
        // $this->db->order_by("dtime", "asc");
        $srcs = $this->db->get($tbl_1)->result_array();
        // showLast_query("biru");

        // arrPrintHijau($srcs);
        foreach ($srcs as $src) {
            $tr_id = $src['extern_id'];
            $qty_debet = $src['qty_debet'];

            $srcDatas[$tr_id] = $qty_debet;
        }

        return $srcDatas;
    }

    public function doResetMobile()
    {
        $this->load->model("Mdls/MdlProdukPerSerialNumberLocker");
        $psl = New MdlProdukPerSerialNumberLocker();

        $produk_id = url_segment(5);
        $cCode = $this->cCode;
        $jenisTr = $this->jenisTr;
        // arrPrint(url_segment());
        // arrPrint($_SESSION[$cCode]['items']);
        // arrPrint($_SESSION[$cCode]['items'][$produk_id]);
        $serialNumberLocker = isset($this->configUi[$this->jenisTr]['serialNumberLocker']['enabled']) ? $this->configUi[$this->jenisTr]['serialNumberLocker']['enabled'] : false;
        $scanQrValidator = isset($this->configUi[$this->jenisTr]['scanQrValidator']) ? $this->configUi[$this->jenisTr]['scanQrValidator'] : array();
        if (sizeof($scanQrValidator) > 0) {
            if (isset($scanQrValidator["enabled"]) && ($scanQrValidator["enabled"] == true)) {
                // mereset hasil scan yang masuk session items5_sum (scan terima distribusi)
                if (isset($_SESSION[$cCode]['items5_sum'])) {
                    foreach ($_SESSION[$cCode]['items5_sum'] as $ii => $iiSpec) {
                        if ($produk_id == $iiSpec["id"]) {
                            $_SESSION[$cCode]['items5_sum'][$ii] = null;
                            unset($_SESSION[$cCode]['items5_sum'][$ii]);
                        }
                    }
                }
            }
        }
        else {
            if ($_SESSION[$cCode]['items'][$produk_id]) {
                //                mati_disini(__LINE__);
                // $_SESSION[$cCode]['items'][$produk_id]['jml_scan'] = null;
                unset($_SESSION[$cCode]['items'][$produk_id]['jml_scan']);
                //            unset($_SESSION[$cCode]['items2'][$produk_id]);
                foreach ($_SESSION[$cCode]['items2'][$produk_id] as $pSku => $xxx) {

                    if ($serialNumberLocker == true) {
                        foreach ($xxx as $scode => $ccc) {
                            $data = array(
                                "jumlah" => 0,
                            );
                            $where = array(
                                "produk_serial_number" => "$scode",
                                "cabang_id" => my_cabang_id(),
                            );
                            $psl->updateData($where, $data);
                        }
                    }

                    $_SESSION[$cCode]['items2'][$produk_id][$pSku] = array();
                }
            }
            else {
                //                mati_disini(__LINE__);
                foreach ($_SESSION[$cCode]['items'] as $prod_id => $arr_item) {
                    unset($_SESSION[$cCode]['items'][$prod_id]['jml_scan']);
                }
                foreach ($_SESSION[$cCode]['items2'] as $prod_id => $xxx) {
                    foreach ($xxx as $pSku => $xx) {
                        if ($serialNumberLocker == true) {
                            foreach ($xx as $scode => $ccc) {
                                $data = array(
                                    "jumlah" => 0,
                                );
                                $where = array(
                                    "produk_serial_number" => "$scode",
                                    "cabang_id" => my_cabang_id(),
                                );
                                $psl->updateData($where, $data);
                            }
                        }
