    public function doKalkulasiMobile()
    {

        $produk_id = url_segment(5);
        $intoStep = $this->uri->segment(6);
        $fromStep = $this->uri->segment(7);
        $cCode = $this->cCode;
        $jenisTr = $this->jenisTr;
        $items = blobDecode($_GET["item"]);
        $itemsSerialSett = blobDecode($_GET["serialSett"]);
        $itemsSerialSettQty = blobDecode($_GET["serialSettQty"]);
        $itemsSerialScan = blobDecode($_GET["itemScan"]);
        //arrPrint($items);
        //arrPrint($itemsSerialSett);
        //arrPrintWebs($itemsSerialSettQty);
        //arrPrintPink($itemsSerialScan);
        //mati_disini(__LINE__);

        $this->load->model("Mdls/MdlProduk2");
        $pr = new MdlProduk2();

        if (sizeof($_SESSION[$cCode]['items']) > 0) {
            //            foreach($_SESSION[$cCode]['items'] as $pidd => $iiSpec){
            //                if ($iiSpec["kategori_nama"] == "unit") {
            //                    if(isset($itemsSerialScan[$pidd])){
            //
            //                    }
            //                    $pNama = $iiSpec['nama'];
            //                    $msg = "Anda belum scan serial produk $pNama. Silahkan scan serial atau hapus dari daftar pengiriman. code: " . __LINE__;
            //                    mati_disini($msg);
            //                }
            //            }

            if (sizeof($items) > 0) {

                foreach ($items as $pid => $jml) {
                    $pNama = $_SESSION[$cCode]['items'][$pid]['nama'];
                    //------------
                    if ($jml == 0) {
                        $msg = "Jumlah scan produk $pNama sebanyak 0. Silahkan diperiksa lagi scan anda atau hapus dari daftar pengiriman bila tidak dikirim. code: " . __LINE__;
                        mati_disini($msg);
                    }
                    //------------
                    foreach ($itemsSerialSettQty[$pid] as $sku => $jml_scan_sku_pasang) {
                        $jml_scan_sku = isset($itemsSerialScan[$pid][$sku]) ? $itemsSerialScan[$pid][$sku] : 0;
                        if ($jml_scan_sku != $jml_scan_sku_pasang) {
                            $msg = "Jumlah scan serial SKU $sku produk $pNama tidak sesuai. Silahkan diperiksa lagi scan anda. code: " . __LINE__;
                            mati_disini($msg);
                        }
                    }
                    //------------
                    //                    mati_disini(__LINE__);
                    $_SESSION[$cCode]['items'][$pid]["jml"] = $jml;
                    $_SESSION[$cCode]['items'][$pid]["qty"] = $jml;
                    $tmp = $_SESSION[$cCode]['items'][$pid];
                    //                    $tmp["jml"] = $jml;
                    //                    $tmp["qty"] = $jml;

                    $pr->setFilters(array());
                    $tmpB = $pr->lookupByID($pid)->result();
                    $produk_jenis = $tmpB[0]->kategori_nama;
                    $arrCode = array();
                    if ($produk_jenis == "unit") {
                        $arrDataTambahan = $this->dataTambahan;
                        foreach ($arrDataTambahan as $cat => $catSpec) {
                            foreach ($catSpec as $dkey => $dval) {
                                if (isset($tmpB[0]->$dval) && ($tmpB[0]->$dval != NULL)) {
                                    //--------------
                                    if (!isset($arrCat[$cat])) {
                                        $arrCat[$cat] = 0;
                                    }
                                    $arrCat[$cat] += 1;
                                    //--------------
                                    if (!isset($arrCode[$tmpB[0]->$dval])) {
                                        $arrCode[$tmpB[0]->$dval] = 0;
                                    }
                                    $arrCode[$tmpB[0]->$dval] += 1;
                                    //--------------
                                }
                            }
                        }
                    }
                    else {
                        if ($tmpB[0]->jml_serial == 1) {
                            $arrCode[$tmpB[0]->kode] = 1;
                        }
                    }

                    $keterangan = "";
                    $static_keterangan = "";
                    if (sizeof($arrCat) > 0) {
                        foreach ($arrCat as $kcat => $vcat) {
                            $new_vcat = $vcat * $jml;
                            if ($keterangan == "") {
                                $keterangan = " $new_vcat $kcat";
                            }
                            else {
                                $keterangan .= "<br> $new_vcat $kcat";
                            }
                            if ($static_keterangan == "") {
                                $static_keterangan = " $vcat $kcat";
                            }
                            else {
                                $static_keterangan .= "<br> $vcat $kcat";
                            }
                            $new_keyy = "qty_" . $kcat;
                            $tmp[$new_keyy] = $vcat;
                        }
                        //                        cekHere(" $keterangan ");
                        $tmp['keterangan'] = $keterangan;

                    }
                    if (sizeof($arrCode) > 0) {
                        foreach ($arrCode as $kcat => $vcat) {
                            $new_vcat = $vcat * $jml;
                            $tmp[$kcat] = $new_vcat;
                            $tmp["jml_" . $kcat] = $vcat;
                        }
                    }

                    $_SESSION[$cCode]['items'][$pid] = $tmp;
                }

            }
        }
        //arrPrint($_SESSION[$cCode]['items']);
        //mati_disini();
        $this->load->helper("he_value_builder");
        resetValues($this->jenisTr);
        fillValues_he_value_builder($this->jenisTr, $fromStep, $intoStep, $this->configCoreJenis, $this->configUiJenis, $this->configValuesJenis);

        /*-------loader ke shoping cart--------------*/
        $shopingcart_mobile = MODUL_PATH . get_class($this) . "/shopingCart/$jenisTr/$produk_id/$intoStep/$fromStep";
        echo "<script>top.$('#shopingcart_mobile').load('$shopingcart_mobile');
        </script>";

    }

