            $qrbase = MODUL_PATH . "FollowUp/followupDariHp/$trjenis/$transaksiID_reference/$stepNum/$stepNumCurrent?ismob=1&a_login=$login";

            $this->load->library("Ciqrcode");
            $qr = new Ciqrcode();
