            $content .= "</div>";
            $content .= "<div class='text-center text-bold text-uppercase text-red' style='font-size: 16px;margin-top: 10px'>scan QR mengunakan handphone untuk melakukan pemindaian barcode <br>dari barang yang baru datang</div>";
            $content .= "<div class='text-center' style='font-size: 12px;margin-top: 10px;color: #ddd;'>$qrbase</div>";
            $content .= "<div class='text-center' style='font-size: 12px;margin-top: 10px;color: #ddd;'><button type='button' onclick=\"location.href='$qrbase'\" class='btn btn-info text-capitalize'>buka dari desktop</button></div>";

            $var .= $content;
        }

        echo $var;
    }

