            if (isset($printSettings['size'])) {
                switch ($printSettings['size']) {
                    case "normal":
                        //                        cekkuning("size: NORMAL");
                        echo "<script>";
                        echo "top.popBig('" . MODUL_PATH . $printLocation . "/" . $this->jenisTr . "/$tmpNomorNota2');";
                        echo "top.location.reload();";
                        echo "</script>";
                        break;
                    case "small":
